// Part: joinery. Fanlit front doors on both floors, tall shuttered windows in every opening the shell left open,
// the garden and service doors at the ends, the rear porch door and the hall chandeliers.
// The grand stair is the stair joiner's (parts/stairs.mjs), so it is not built here.
import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { fanlitDoor, tallWindow, shutterPair, porchLantern } from "../vocab.mjs";

const PANE = { north: "true", south: "true", east: "false", west: "false" };

// A double door in a wall running along z (east or west end): leaves at z and z+1 on rows y..y+1, glass transom above.
function endDoor(g, x, z, facing, y = 4) {
  const hinges = ["left", "right"];
  [z, z + 1].forEach((zz, i) => {
    g.set(x, y, zz, ...B.door("dark_oak", facing, "lower", hinges[i]));
    g.set(x, y + 1, zz, ...B.door("dark_oak", facing, "upper", hinges[i]));
  });
  for (let yy = y + 2; yy <= y + 4; yy++) for (const zz of [z, z + 1]) g.set(x, yy, zz, "glass_pane", PANE);
}

// A double door in a wall running along x (north or south face): leaves at x and x+1, glass transom above.
function faceDoor(g, x, z, facing, y = 4) {
  const hinges = ["left", "right"];
  [x, x + 1].forEach((xx, i) => {
    g.set(xx, y, z, ...B.door("dark_oak", facing, "lower", hinges[i]));
    g.set(xx, y + 1, z, ...B.door("dark_oak", facing, "upper", hinges[i]));
  });
  for (let yy = y + 2; yy <= y + 4; yy++) for (const xx of [x, x + 1]) g.set(xx, yy, z, "glass_pane", { east: "true", west: "true", north: "false", south: "false" });
}

export function build(g) {
  // ---- front (north) wall z42: fanlit double doors on both floors
  fanlitDoor(g, 45, 4, 42, "north", { height: 6 });
  fanlitDoor(g, 45, 11, 42, "north", { height: 5 });

  // ---- front windows: ground y4..8 (floor is the sill), upper y11..15; shutters flat on z41
  for (const x of [28, 34, 40, 54, 60, 66]) {
    tallWindow(g, x, 42, "north", 4, 5, { sill: false });
    shutterPair(g, x, x + 1, 4, 5, "north", 42);
    tallWindow(g, x, 42, "north", 11, 5, { sill: false });
    shutterPair(g, x, x + 1, 11, 5, "north", 42);
  }

  // ---- end walls (west x26, east x69): windows at z45..46 and z58..59, garden / service door at z51..52
  for (const x of [26, 69]) {
    const face = x === 26 ? "west" : "east";
    for (const z of [45, 58]) {
      tallWindow(g, x, z, face, 5, 4, { sill: false });
      shutterPair(g, z, z + 1, 5, 4, face, x);
      tallWindow(g, x, z, face, 12, 4, { sill: false });
      shutterPair(g, z, z + 1, 12, 4, face, x);
    }
    endDoor(g, x, 51, face);
    tallWindow(g, x, 51, face, 12, 4, { sill: false });
    shutterPair(g, 51, 52, 12, 4, face, x);
  }

  // ---- south wall z61 (main block, outside the wing): windows, shutters on z62
  for (const x of [29, 33, 61, 65]) {
    tallWindow(g, x, 61, "south", 5, 4, { sill: false });
    shutterPair(g, x, x + 1, 5, 4, "south", 61);
    tallWindow(g, x, 61, "south", 12, 4, { sill: false });
    shutterPair(g, x, x + 1, 12, 4, "south", 61);
  }

  // ---- rear wing: living room west windows (x37), kitchen east windows (x58), south windows (z75)
  for (const z of [65, 70]) {
    tallWindow(g, 37, z, "west", 5, 8, { sill: false });
    tallWindow(g, 58, z, "east", 5, 4, { sill: false });
    tallWindow(g, 58, z, "east", 12, 4, { sill: false });
  }
  // Palladian window: side lights x40..41 and x44..45 (y5..12), arched centre x42..43 (y5..15)
  tallWindow(g, 40, 75, "south", 5, 8, { sill: false });
  tallWindow(g, 44, 75, "south", 5, 8, { sill: false });
  tallWindow(g, 42, 75, "south", 5, 11, { sill: false });
  // kitchen and bedroom windows on the south face
  for (const x of [50, 54]) {
    tallWindow(g, x, 75, "south", 5, 4, { sill: false });
    tallWindow(g, x, 75, "south", 12, 4, { sill: false });
  }

  // ---- rear porch door between the living and kitchen halves (x47..48, z75)
  faceDoor(g, 47, 75, "south", 4);

  // ---- hall chandeliers: ground hall (y9 chain, lantern y8) and upper hall (y16 chain, lantern y15)
  porchLantern(g, 47, 9, 47);
  porchLantern(g, 48, 9, 56);
  porchLantern(g, 47, 16, 47);
  porchLantern(g, 48, 16, 56);
}
